#include <iostream>
using std::cin;
using std::cout;
using std::cerr;
using std::endl;

int main (void) {
	int x, y, l, r, a, b;
	cin >> x >> y >> l >> r >> a >> b;

	int sum = 0;
	for (int i = a; i <= b-1; i++) {
		// cost of i-th hour
		if (l <= i && i <= r-1) {
			sum += x;
		} else {
			sum += y;
		}
	}

	cout << sum << "\n";

	return 0;
}
